create table public.analises_ia (id uuid primary key default gen_random_uuid(), raw_id uuid not null references public.intimacoes_djen_raw(id) on delete cascade, modelo text not null, status public.status_analise_ia not null, resumo text, acao_sugerida text, prazo_texto text, prazo_data date, trecho_fundamentador text, pendencias jsonb not null default '[]'::jsonb, motivo_falha text, duracao_ms integer, criado_por uuid, criado_em timestamp with time zone not null default now())